def rearange_string(string):
    # Create a dictionary to store the frequency of each character
    char_freq = {}
    for char in string:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Create a list to store the rearranged string
    rearranged_string = []

    # Iterate through the characters in the string
    for char in string:
        # If the character is already in the rearranged string, skip it
        if char in rearranged_string:
            continue

        # If the character has a frequency of 1, add it to the rearranged string
        if char_freq[char] == 1:
            rearranged_string.append(char)
            char_freq[char] -= 1
        # If the character has a frequency greater than 1, add it to the rearranged string
        # and decrement its frequency
        else:
            rearranged_string.append(char)
            char_freq[char] -= 1

    # Return the rearranged string
    return ''.join(rearranged_string)

