import heapq

def merge_sorted_list(list1, list2, list3):
    merged_list = []
    heapq.heapify(list1)
    heapq.heapify(list2)
    heapq.heapify(list3)
    while len(list1) > 0 and len(list2) > 0 and len(list3) > 0:
        if list1[0] < list2[0] and list1[0] < list3[0]:
            merged_list.append(list1[0])
            heapq.heappop(list1)
        elif list2[0] < list1[0] and list2[0] < list3[0]:
            merged_list.append(list2[0])
            heapq.heappop(list2)
        else:
            merged_list.append(list3[0])
            heapq.heappop(list3)
    while len(list1) > 0:
        heapq.heappop(list1)
        merged_list.append(list1[0])
    while len(list2) > 0:
        heapq.heappop(list2)
        merged_list.append(list2[0])
    while len(list3) > 0:
        heapq.heappop(list3)
        merged_list.append(list3[0])
    return merged_list

