    n = len(heap)
    for i in range(n//2-1, -1, -1):
        heapify_down(heap, i, n)

def heapify_down(heap, i, n):
    while 2*i+1 < n:
        j = 2*i+1
        if j+1 < n and heap[j+1] > heap[j]:
            j += 1
        if heap[i] >= heap[j]:
            break
        heap[i], heap[j] = heap[j], heap[i]
        i = j

