import heapq

def heap_queue_smallest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
    smallest = []
    for _ in range(k):
        smallest.append(heapq.heappop(heap))
    return smallest

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def concatenate_elements(lst):
    result = ''
    for element in lst:
        result += element
    return result

def num_comm_div(a, b):
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            return i

def add_consecutive_nums(nums):
    result = []
    for i in range(len(nums)-1):
        result.append(nums[i] + nums[i+1])
    return result

def re_order(arr):
    non_zero = []
    for i in arr:
        if i != 0:
            non_zero.append(i)
    return non_zero + [0] * (len(arr) - len(non_zero))

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            return False
    return True

def no_of_subsequences(arr, k):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i]*arr[j] < k:
                count += 1
    return count
